insert into public.knowledge_chunks (id, source, kind, cite, doi, strength, body) values
  ('biskas-2023#shows', 'biskas-2023', 'shows', 'Biskas, Sirois & Webb (2023). Does psychoeducation help people to respond to goal lapses with self-compassion? Journal of Psychoeducational Assessment 41(8), 839-851.', '10.1177/07342829231189010', 'moderate', 'In a randomised study, participants received self-compassion psychoeducation or a control, then responded to a goal lapse they recalled. The education seemed to change beliefs about self-compassion, but there was no evidence that it increased self-compassionate responding to the lapse.'),
  ('biskas-2023#limits', 'biskas-2023', 'limits', 'Biskas, Sirois & Webb (2023). Does psychoeducation help people to respond to goal lapses with self-compassion? Journal of Psychoeducational Assessment 41(8), 839-851.', '10.1177/07342829231189010', 'moderate', 'A null result on the response outcome; the sample size is not in the abstract. It does not show that self-compassion is useless, only that telling people about it was not enough; the authors say other strategies are needed.'),
  ('buyalskaya-2023#shows', 'buyalskaya-2023', 'shows', 'Buyalskaya, Ho, Milkman, Li, Duckworth & Camerer (2023). What can machine learning teach us about habit formation? Evidence from exercise and hygiene. PNAS 120(17).', '10.1073/pnas.2216115120', 'strong', 'Machine-learning analysis of objective data: gym attendance (over 12 million observations) and hospital handwashing (over 40 million). Contrary to the belief in a "magic number" of days, forming the gym habit typically took months, while the handwashing habit took weeks. Gymgoers who were more predictable were less responsive to an intervention designed to increase attendance.'),
  ('buyalskaya-2023#limits', 'buyalskaya-2023', 'limits', 'Buyalskaya, Ho, Milkman, Li, Duckworth & Camerer (2023). What can machine learning teach us about habit formation? Evidence from exercise and hygiene. PNAS 120(17).', '10.1073/pnas.2216115120', 'strong', 'Two specific behaviours in adults (gym members, hospital workers); the abstract does not generalise to other habits or to teenagers. Time to habit is inferred from how predictable behaviour becomes, not from self-report.'),
  ('dai-2014#shows', 'dai-2014', 'shows', 'Dai, Milkman & Riis (2014). The fresh start effect: Temporal landmarks motivate aspirational behavior. Management Science.', '10.1287/mnsc.2014.1901', 'moderate', 'Three archival field studies found that Google searches for "diet", gym visits at a university gym and goal commitments on stickK.com rose after temporal landmarks such as the start of a new week, month, year or semester, and after birthdays and holidays. The authors propose that fresh starts create a sense of separation from past selves and past failures.'),
  ('dai-2014#limits', 'dai-2014', 'limits', 'Dai, Milkman & Riis (2014). The fresh start effect: Temporal landmarks motivate aspirational behavior. Management Science.', '10.1287/mnsc.2014.1901', 'moderate', 'Archival, observational data from adults and university students; it shows an association with landmarks, not that a plan made on a landmark works better for a given person. No replication from 2022 onward was found.'),
  ('fogg-2009#shows', 'fogg-2009', 'shows', 'Fogg (2009). A behavior model for persuasive design. Proceedings of the 4th International Conference on Persuasive Technology.', '10.1145/1541948.1541999', 'theory', 'Behaviour happens when three elements converge at the same moment: motivation, ability and a trigger. Motivation and ability can offset each other, so high motivation can compensate for low ability, and making a behaviour easier raises the chance it happens.'),
  ('fogg-2009#limits', 'fogg-2009', 'limits', 'Fogg (2009). A behavior model for persuasive design. Proceedings of the 4th International Conference on Persuasive Technology.', '10.1145/1541948.1541999', 'theory', 'A conceptual design model, not an experimental result; later versions renamed the trigger "prompt" (B=MAP).'),
  ('gollwitzer-1999#shows', 'gollwitzer-1999', 'shows', 'Gollwitzer (1999). Implementation intentions: Strong effects of simple plans. American Psychologist 54, 493-503.', '10.1037/0003-066X.54.7.493', 'theory', 'If-then plans link an anticipated situation to a planned response, so that the response is triggered more automatically when the situation occurs. The paper summarises a research programme showing that such plans improve goal attainment.'),
  ('gollwitzer-1999#limits', 'gollwitzer-1999', 'limits', 'Gollwitzer (1999). Implementation intentions: Strong effects of simple plans. American Psychologist 54, 493-503.', '10.1037/0003-066X.54.7.493', 'theory', 'A review by the researcher who proposed the idea; it does not give one pooled effect size. For effect sizes use sheeran-2025.'),
  ('lally-2010#shows', 'lally-2010', 'shows', 'Lally, van Jaarsveld, Potts & Wardle (2010). How are habits formed: Modelling habit formation in the real world. European Journal of Social Psychology 40(6), 998-1009.', '10.1002/ejsp.674', 'moderate', 'Participants chose a daily eating, drinking or activity behaviour and performed it in the same context for 12 weeks, reporting automaticity daily. For the 39 of 62 participants whose data fitted the model well, the time to reach 95% of the asymptote of automaticity ranged from 18 to 254 days. Missing one opportunity to perform the behaviour did not materially affect the habit formation process.'),
  ('lally-2010#limits', 'lally-2010', 'limits', 'Lally, van Jaarsveld, Potts & Wardle (2010). How are habits formed: Modelling habit formation in the real world. European Journal of Social Psychology 40(6), 998-1009.', '10.1002/ejsp.674', 'moderate', 'Depends on self-reported automaticity, and a good model fit was found for 39 of the 62 modelled participants. The "21 days" figure has no support here; the range shows large individual differences.'),
  ('ma-2023#shows', 'ma-2023', 'shows', 'Ma, Wang, Pei & Piao (2023). Effects of habit formation interventions on physical activity habit strength: meta-analysis and meta-regression. International Journal of Behavioral Nutrition and Physical Activity 20, 109.', '10.1186/s12966-023-01493-3', 'moderate', 'Meta-analysis of 10 studies of habit formation interventions for physical activity: they significantly increased habit strength (SMD = 0.31, 95% CI 0.14-0.48). Follow-up of 12 weeks or less showed a larger effect than longer follow-up. In meta-regression, problem solving was associated with greater effectiveness (beta = 0.36, 95% CI 0.17-0.55).'),
  ('ma-2023#limits', 'ma-2023', 'limits', 'Ma, Wang, Pei & Piao (2023). Effects of habit formation interventions on physical activity habit strength: meta-analysis and meta-regression. International Journal of Behavioral Nutrition and Physical Activity 20, 109.', '10.1186/s12966-023-01493-3', 'moderate', 'Only 10 studies and only physical activity; the outcome is habit strength, not long-term behaviour. The association of social reward with lower effectiveness (beta = -0.40) has a confidence interval that reaches zero (-0.74 to 0.06), so it is weak evidence.'),
  ('sheeran-2025#shows', 'sheeran-2025', 'shows', 'Sheeran, Listrom & Gollwitzer (2025). The when and how of planning: Meta-analysis of the scope and components of implementation intentions in 642 tests. European Review of Social Psychology 36(1), 162-194.', '10.1080/10463283.2024.2334563', 'strong', 'Meta-analysis of 642 tests of implementation intentions (if-then plans). They were effective for cognitive, affective and behavioural outcomes (.27 <= d <= .66). Effects were larger for plans in the if-then format, when people were highly motivated, and when plans were rehearsed.'),
  ('sheeran-2025#limits', 'sheeran-2025', 'limits', 'Sheeran, Listrom & Gollwitzer (2025). The when and how of planning: Meta-analysis of the scope and components of implementation intentions in 642 tests. European Review of Social Psychology 36(1), 162-194.', '10.1080/10463283.2024.2334563', 'strong', 'd is a standardised effect size, not a percentage of people who succeed. The pooled studies cover many populations and behaviours; the abstract does not single out teenagers or app users. It is not a guarantee for any one person.'),
  ('silverman-2023#shows', 'silverman-2023', 'shows', 'Silverman & Barasch (2023). On or off track: How (broken) streaks affect consumer decisions. Journal of Consumer Research 49(6), 1095-1117.', '10.1093/jcr/ucac029', 'moderate', 'Across seven studies, highlighting intact streaks in a behaviour log increased later engagement compared with highlighting broken streaks, depending on how past behaviour was represented rather than on what was actually done. People treat maintaining a logged streak as a goal in itself. The effect was stronger when people attributed the break to their own actions and weaker when they could repair a broken streak.'),
  ('silverman-2023#limits', 'silverman-2023', 'limits', 'Silverman & Barasch (2023). On or off track: How (broken) streaks affect consumer decisions. Journal of Consumer Research 49(6), 1095-1117.', '10.1093/jcr/ucac029', 'moderate', 'Experiments on how streaks are displayed; the abstract reports no long-term field trial of a habit app and no teenage sample. The abstract does not state limitations.'),
  ('singh-2024#shows', 'singh-2024', 'shows', 'Singh, Murphy, Maher & Smith (2024). Time to form a habit: A systematic review and meta-analysis of health behaviour habit formation and its determinants. Healthcare 12(23), 2488.', '10.3390/healthcare12232488', 'moderate', 'Systematic review and meta-analysis of 20 studies with 2601 participants. Four studies reported time to habit formation: medians of 59-66 days and means of 106-154 days, with individual variability from 4 to 335 days. Habit scores rose from pre to post intervention (SMD 0.69, 95% CI 0.49-0.88). Frequency, timing, type of habit and individual choice influenced habit strength; morning practices and self-selected habits generally showed greater strength.'),
  ('singh-2024#limits', 'singh-2024', 'limits', 'Singh, Murphy, Maher & Smith (2024). Time to form a habit: A systematic review and meta-analysis of health behaviour habit formation and its determinants. Healthcare 12(23), 2488.', '10.3390/healthcare12232488', 'moderate', '11 of the 20 studies had a high risk of bias, the time-to-habit figures rest on only four studies, and flossing and diet had the most evidence. "About two months" is an order of magnitude, not a deadline.'),
  ('wood-neal-2007#shows', 'wood-neal-2007', 'shows', 'Wood & Neal (2007). A new look at habits and the habit-goal interface. Psychological Review 114(4), 843-863.', '10.1037/0033-295X.114.4.843', 'theory', 'Habits form gradually from links between responses and the contexts in which they were repeatedly performed; once formed, a habit can be triggered by the context alone, without a mediating goal. Goals can help build habits through repetition and by exposing people to habit-triggering cues. The paper discusses changing habits by self-regulating habit cues.'),
  ('wood-neal-2007#limits', 'wood-neal-2007', 'limits', 'Wood & Neal (2007). A new look at habits and the habit-goal interface. Psychological Review 114(4), 843-863.', '10.1037/0033-295X.114.4.843', 'theory', 'A theoretical integration, not a trial of an intervention.')
